UPDATE COURSE_HOMEWORK
   SET CONTENT  = #{modifyHomeworkVO.content}
     , END_DATE = #{modifyHomeworkVO.endDate}
     , MDFY_DT  = SYSDATE
 WHERE COURSE_ID = #{courseId}
   AND ID        = #{homeworkId}
   AND DEL_YN    = 'N'

UPDATE COURSE_HOMEWORK_REPLY
   SET CONTENT = #{content}
     , MDFY_DT = SYSDATE
 WHERE ID                = #{id}
   AND HOMEWORK_ID       = #{homeworkId}
   AND COURSE_STUDENT_ID = #{courseStudentId}
   AND DEL_YN            = 'N'

UPDATE COURSE_HOMEWORK
   SET DEL_YN  = 'Y'
     , MDFY_DT = SYSDATE
 WHERE COURSE_ID = #{courseId}
   AND ID        = #{homeworkId}
   AND DEL_YN    = 'N'

UPDATE COURSE_HOMEWORK_REPLY
   SET DEL_YN  = 'Y'
     , MDFY_DT = SYSDATE
 WHERE ID          = #{replyId}
   AND HOMEWORK_ID = #{homeworkId}
   AND DEL_YN      = 'N'

mapper.select:
SELECT COUNT(1)
  FROM COURSE_TUTOR CT
 WHERE CT.COURSE_ID = #{courseId}
   AND CT.TUTOR_ID  = #{userId}

mapper.update:
UPDATE COURSE
   SET "NO"        = #{no}
     , COURSE_NAME = #{courseName}
     , START_DATE  = TO_DATE(#{startDate}, 'YYYY-MM-DD')
     , END_DATED   = TO_DATE(#{endDated}, 'YYYY-MM-DD')
 WHERE ID     = #{id}
   AND DEL_YN = 'N'

mapper.select:
SELECT CS.USER_ID , U.NAME , COUNT(CASE WHEN A.ATTEND_STATUS = 'Y' THEN 1 END) AS PRESENT_COUNT , COUNT(CASE WHEN A.ATTEND_STATUS = 'L' THEN 1 END) AS LATE_COUNT , COUNT(CASE WHEN A.ATTEND_STATUS = 'N' THEN 1 END) AS ABSENT_COUNT FROM COURSE_STUDENT CS INNER JOIN "USER" U ON U.ID = CS.USER_ID LEFT JOIN ATTENDANCE A ON A.COURSE_ID = CS.COURSE_ID AND A.USER_ID = CS.USER_ID AND A.LGN_DT < TRUNC(SYSDATE) WHERE CS.COURSE_ID = #{courseId}
AND CS.USER_ID = #{userId}
GROUP BY CS.USER_ID, U.NAME ORDER BY U.NAME
